import{describe,it,expect}from"vitest";import{freedomTimeline,revolutionaryOrganizations,freedomLeaders,historicalDocuments,getEventById,filterTimelineEvents,filterRevolutionaryOrgs,filterLeaders,getDocumentById,filterDocuments}from"../../frontend/freedom-movement-explorer/freedom-movement.js";const REQUIRED_TIMELINE_FIELDS=["id","year","date","title","movement","phase","location","description","historicalImpact"];describe("Freedom Movements Timeline Dataset Integrity",()=>{it("contains at least 15 verified events from early uprisings to 1947 independence",()=>{expect(freedomTimeline.length).toBeGreaterThanOrEqual(15),expect(freedomTimeline[0].year).toBe(1770),expect(freedomTimeline[freedomTimeline.length-1].year).toBe(1947)}),it("every timeline event contains required properties with valid text",()=>{freedomTimeline.forEach((e,t)=>{REQUIRED_TIMELINE_FIELDS.forEach(i=>{expect(e,`Timeline event at index ${t} missing field ${i}`).toHaveProperty(i),"string"==typeof e[i]?expect(e[i].trim().length).toBeGreaterThan(0):"number"==typeof e[i]&&expect(e[i]).toBeGreaterThan(1700)})})}),it("all timeline event IDs are unique",()=>{const e=freedomTimeline.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Timeline Query Helpers",()=>{it("retrieves timeline event by ID",()=>{const e=getEventById("evt-1905-swadeshi");expect(e).toBeDefined(),expect(e.title).toContain("Swadeshi")}),it("filters timeline events by movement category",()=>{const e=filterTimelineEvents("","Quit India");expect(e.length).toBeGreaterThan(0),expect(e.every(e=>"Quit India"===e.movement)).toBe(!0)}),it("filters timeline events by search query (e.g. Salt or Bose or Kakori)",()=>{const e=filterTimelineEvents("Salt");expect(e.length).toBeGreaterThan(0);const t=filterTimelineEvents("Bose");expect(t.length).toBeGreaterThan(0)}),it("returns empty array when search query matches nothing",()=>{const e=filterTimelineEvents("NonExistentFreedomEventXYZ");expect(e).toEqual([])})}),describe("Revolutionary Organizations Catalog",()=>{it("contains major revolutionary groups (Anushilan, Jugantar, Abhinav Bharat, Ghadar, HSRA, INA)",()=>{expect(revolutionaryOrganizations.length).toBeGreaterThanOrEqual(6);const e=revolutionaryOrganizations.map(e=>e.name);expect(e.some(e=>e.includes("Anushilan"))).toBe(!0),expect(e.some(e=>e.includes("Ghadar"))).toBe(!0),expect(e.some(e=>e.includes("HSRA")||e.includes("Hindustan"))).toBe(!0)}),it("filters revolutionary organizations by keyword",()=>{const e=filterRevolutionaryOrgs("Socialist");expect(e.length).toBe(1),expect(e[0].name).toContain("HSRA")})}),describe("Freedom Leaders Catalog",()=>{it("contains comprehensive leader profiles across all freedom struggle categories",()=>{expect(freedomLeaders.length).toBeGreaterThanOrEqual(15);const e=freedomLeaders.map(e=>e.name);expect(e).toContain("Mahatma Gandhi"),expect(e).toContain("Netaji Subhas Chandra Bose"),expect(e).toContain("Bhagat Singh"),expect(e).toContain("Sarojini Naidu"),expect(e).toContain("Aruna Asaf Ali")}),it("filters leaders by category",()=>{const e=filterLeaders("Revolutionary");expect(e.length).toBeGreaterThan(0),expect(e.some(e=>"Revolutionary"===e.category)).toBe(!0)})}),describe("Primary Historical Documents Archive",()=>{it("contains landmark speeches and declarations (Poorna Swaraj, Tryst with Destiny, etc.)",()=>{expect(historicalDocuments.length).toBeGreaterThanOrEqual(8);const e=getDocumentById("doc-poorna-swaraj");expect(e).toBeDefined(),expect(e.title).toContain("Poorna Swaraj")}),it("filters historical documents by search query",()=>{const e=filterDocuments("destiny");expect(e.length).toBe(1),expect(e[0].author).toContain("Nehru")})});